CREATE TABLE customers (id int PRIMARY KEY, name text NOT NULL, region text);
CREATE TABLE orders (id int PRIMARY KEY, customer_id int NOT NULL REFERENCES customers (id), amount numeric(10,2), status text);
CREATE TABLE items (id int PRIMARY KEY, sku text, qty int, note text);
CREATE TABLE logs (id int, msg text);
CREATE TABLE audit (id int, msg text);
CREATE VIEW v_customers AS SELECT id, name FROM customers;
CREATE TYPE mood AS ENUM ('happy', 'sad');
CREATE FUNCTION f_double(x int) RETURNS int LANGUAGE sql IMMUTABLE AS 'SELECT x * 2';
CREATE FUNCTION f_log_count() RETURNS bigint LANGUAGE sql AS 'SELECT count(*) FROM logs';
CREATE FUNCTION f_item_qty(i int) RETURNS int LANGUAGE sql BEGIN ATOMIC SELECT qty FROM items WHERE id = i; END;
CREATE FUNCTION f_quad(x int) RETURNS int LANGUAGE sql RETURN f_double(f_double(x));
CREATE FUNCTION f_names() RETURNS SETOF text LANGUAGE sql BEGIN ATOMIC SELECT name FROM v_customers; END;
CREATE FUNCTION f_mood(m mood) RETURNS text LANGUAGE sql RETURN m::text;
CREATE FUNCTION f_over(x int) RETURNS int LANGUAGE sql AS 'SELECT x';
CREATE FUNCTION f_over(x text) RETURNS text LANGUAGE sql AS 'SELECT x';
CREATE FUNCTION f_total(c int) RETURNS numeric LANGUAGE plpgsql AS $$ DECLARE s numeric; BEGIN SELECT sum(amount) INTO s FROM orders WHERE customer_id = c; RETURN s; END $$;
CREATE PROCEDURE p_log(m text) LANGUAGE plpgsql AS $$ BEGIN INSERT INTO logs (msg) VALUES (m); END $$;
CREATE PROCEDURE p_audit(m text) LANGUAGE sql BEGIN ATOMIC INSERT INTO audit (msg) VALUES (m); END;
CREATE PROCEDURE p_bump(INOUT n int) LANGUAGE plpgsql AS $$ BEGIN n := n + 1; END $$;
CREATE PROCEDURE p_broken() LANGUAGE plpgsql AS $$ BEGIN INSERT INTO missing_t VALUES (1); END $$;
CREATE FUNCTION trg_status() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.status := coalesce(NEW.status, 'new'); RETURN NEW; END $$;
CREATE TRIGGER orders_status BEFORE INSERT ON orders FOR EACH ROW EXECUTE FUNCTION trg_status();
CREATE FUNCTION evt_note() RETURNS event_trigger LANGUAGE plpgsql AS $$ BEGIN RAISE NOTICE 'ddl'; END $$;
CREATE EVENT TRIGGER evt_existing ON ddl_command_end EXECUTE FUNCTION evt_note();
